set)
  [ "$#" -eq 4 ] && [ "$3" = --why ] || die 'usage: set KEY VALUE --why TEXT'
  setting "$1" "$2"; reason_check "$4"
  {
    header; printf '%s\n' 'BEGIN IMMEDIATE;'; input_table
    policy_sql "$1" "$2" "$4"
    printf '%s\n' "CREATE TEMP TABLE report AS SELECT 'Policy receipt '||id||': '||state AS result FROM head;" 'COMMIT;' 'SELECT result FROM report;'
  } | sqlite3 "$DB"
  ;;

for (const key of ["water", "food", "soil"]) {
  text(key, state[key]);
  $(key + "-meter").value = state[key];
  $(key + "-meter").low = state[key + "_floor"];
  text(key + "-detail", "Protected floor " + state[key + "_floor"] +
    " · room above it: " + (state[key] - state[key + "_floor"]));
}
for (let i = 1; i <= 3; i++) $("bed-" + i).style.opacity = i <= state.beds ? "1" : ".35";
text("next-action", next.safe ?
  "Next day: tend " + next.irrigated + " beds, harvest " + next.harvest +
    ", return " + next.compost + " food to the soil." :
  "The next day pauses: " + next.stop_reason + ".");
text("provenance", "Physics 1 · head " + world.head.hash.slice(0, 12));
const history = world.events.filter(e => e.kind === "genesis" || e.kind === "tick").slice(-37);

